import {studioView,mountStudio,leaveStudio} from './practice-studio.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const passage='A small library in Brighton recently changed its opening hours. It used to close at five every afternoon, which made it difficult for people with full-time jobs to visit. The library now stays open until eight on Tuesdays and Thursdays. Rather than hiring more staff, the team moved some working hours from quiet mornings to busy evenings. During the first month, evening visits doubled. However, the number of books borrowed did not rise as quickly. Many visitors came to use the study spaces or attend a free conversation club. The library manager says that borrowing figures alone cannot show the value of a public library.';
const transcript='Hello everyone. This is a reminder about our study group this Saturday. We were going to meet at the central library, but its meeting room is being repaired. We will meet at Riverside Cafe instead. Please arrive at ten fifteen, so we can begin at ten thirty. Bring a notebook and the article I sent yesterday. There is no need to print it: reading it on your phone is fine. The session costs nothing, but please buy your own drink if you want one.';
const sets={reading:{title:'Reading studio',label:'B1 · Asosiy fikr va tafsilotlar',text:passage,questions:[['Why did the library change its hours?',['To help people who work during the day','To reduce evening visits','To close on Thursdays'],0],['How did the library cover the new hours?',['It hired a new team','It rearranged staff working hours','It stopped opening in the morning'],1],['What does the manager suggest?',['All visitors should borrow books','Conversation clubs should charge a fee','Libraries offer more than borrowed books'],2]]},listening:{title:'Listening studio',label:'B1 · E’lonni tinglash',text:transcript,questions:[['Where will the group meet?',['Central library','Riverside Cafe','At school'],1],['When should participants arrive?',['10:00','10:15','10:30'],1],['What must participants bring?',['A printed article','A drink','A notebook'],2]]}};
let activeAudio=null;
export function leaveSkills(){leaveStudio();if(activeAudio){speechSynthesis.cancel();activeAudio=null;}}
export function skillsView(kind){if(kind!=='writing')return studioView(kind);
 const head=(title,label)=>`<div class="page-heading"><div><span class="eyebrow">MUSTAQIL MASHQ · ${label}</span><h1>${title}</h1><p>Bir ko‘nikma. Diqqat bilan bajarilgan bitta mashq.</p></div><a href="#home" class="btn">Kabinetga qaytish</a></div>`;
 if(kind==='writing')return head('Writing studio','MATN YOZISH')+`<div class="studio-layout"><section class="studio-paper"><span class="eyebrow">IELTS TASK 2 · OPINION</span><h2>Should schools teach practical life skills?</h2><p>Some people believe that schools should teach practical skills, such as managing money and cooking, alongside academic subjects. To what extent do you agree or disagree?</p><hr><h3>Yozish rejasi</h3><ol><li>Pozitsiyangizni aniq ayting.</li><li>Ikki asosiy fikrni misollar bilan tushuntiring.</li><li>Xulosada fikrlaringizni birlashtiring.</li></ol><p class="help-text">250+ so‘z yozishni mashq qiling. Bu mustaqil mashq; AI bahosi yoki o‘qituvchiga yuborish hali ulanmagan.</p></section><section class="studio-paper"><div class="section-heading"><h2>Sizning matningiz</h2><output id="writing-count">0 so‘z</output></div><label for="writing-draft" class="sr-only">Inglizcha insho</label><textarea id="writing-draft" class="writing-draft" placeholder="Start with your introduction…"></textarea><p id="writing-save" role="status">Qoralama shu qurilmada saqlanadi.</p><button class="btn primary" id="writing-download">Matnni yuklab olish ↓</button></section></div>`;
 const set=sets[kind];return head(set.title,set.label)+`<div class="studio-layout"><section class="studio-paper"><span class="eyebrow">${kind==='reading'?'01 / READ':'01 / LISTEN'}</span><h2>${kind==='reading'?'A library after hours':'A change of plan'}</h2>${kind==='reading'?`<p class="reading-passage">${set.text}</p>`:`<div class="listen-player"><button class="btn primary" id="listen-play">▶ Tinglash</button><button class="btn" id="listen-stop">To‘xtatish</button><label>Tezlik<select id="listen-rate"><option value="0.85">0.85×</option><option value="1" selected>1×</option></select></label></div><p class="help-text">Qurilmangizning inglizcha ovozi yordamida o‘qiladi.</p><details><summary>Tinglagandan keyin matnni ochish</summary><p class="reading-passage">${set.text}</p></details><p id="listen-status" role="status"></p>`}</section><section class="studio-paper"><span class="eyebrow">02 / CHECK</span><h2>Tushunganingizni tekshiring</h2><form id="skill-quiz">${set.questions.map(([q,options],i)=>`<fieldset><legend>${i+1}. ${q}</legend>${options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" required> ${escape(o)}</label>`).join('')}</fieldset>`).join('')}<button class="btn primary">Javoblarni tekshirish →</button><div id="skill-result" role="status"></div></form></section></div>`;
}
export function mountSkills(kind,accountId){if(kind!=='writing')return mountStudio(kind,accountId);
 const $=s=>document.querySelector(s);
 if(kind==='writing'){
  const draft=$('#writing-draft'),key='lexora.writing.'+accountId;try{draft.value=localStorage.getItem(key)||'';}catch{}
  const count=()=>{$('#writing-count').textContent=(draft.value.trim().match(/\S+/g)||[]).length+' so‘z';};count();
  draft.oninput=()=>{count();try{localStorage.setItem(key,draft.value);$('#writing-save').textContent='Qoralama shu qurilmada saqlandi.';}catch{$('#writing-save').textContent='Saqlanmadi. Matnni yuklab oling.';}};
  $('#writing-download').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([draft.value],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='lexora-writing.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};return;
 }
 const set=sets[kind];$('#skill-quiz').onsubmit=event=>{event.preventDefault();const data=new FormData(event.target),correct=set.questions.filter((q,i)=>Number(data.get('q'+i))===q[2]).length;$('#skill-result').innerHTML=`<h3>${correct} / ${set.questions.length} to‘g‘ri</h3><ul>${set.questions.map(([q,opts,answer],i)=>`<li>${Number(data.get('q'+i))===answer?'✓':'↺'} ${escape(q)} <b>${escape(opts[answer])}</b></li>`).join('')}</ul><p class="help-text">Mustaqil mashq natijasi. Guruh bahosiga qo‘shilmaydi.</p>`;};
 if(kind==='listening'){
  $('#listen-play').onclick=()=>{if(!('speechSynthesis' in window)){$('#listen-status').textContent='Bu qurilmada ovozli o‘qish mavjud emas. Matnni ochishingiz mumkin.';return;}const voice=speechSynthesis.getVoices().find(v=>/^en[-_]/i.test(v.lang));if(!voice){$('#listen-status').textContent='Inglizcha ovoz hali tayyor emas. Qayta urinib ko‘ring yoki qurilmangizga inglizcha ovoz o‘rnating.';return;}leaveSkills();activeAudio=new SpeechSynthesisUtterance(set.text);activeAudio.voice=voice;activeAudio.lang=voice.lang;activeAudio.rate=Number($('#listen-rate').value);activeAudio.onend=()=>{activeAudio=null;};speechSynthesis.speak(activeAudio);};$('#listen-stop').onclick=leaveSkills;
 }
}
